std::vector<int> v = {10, 40};
auto pos = v.begin();

// 1. Positional insertion (O(N) complexity)
// Returns iterator to the newly inserted element
auto new_it = v.insert(pos + 1, 20);
v.insert(new_it + 1, 30);
// v is now {10, 20, 30, 40}


std::set<int> s = {100, 500};
// Hint must be near the desired insertion point (400)
auto hint = s.find(500);

// 2. Hinted insertion (optimization hint for set/map)
// If the hint is accurate, complexity drops from O(log N) to O(1)
auto s_it = s.insert(hint, 400);
// s is now {100, 400, 500}
s.insert(s.end(), 600); // end() is a common general hint
// s_it points to 400
